package com.nimbusbill.customer.service; import com.nimbusbill.customer.dto.*; import com.nimbusbill.customer.entity.*; import com.nimbusbill.customer.exception.*; import com.nimbusbill.customer.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class CustomerConfigurationService{private final CustomerRepository customers;private final PaymentProductRepository products;private final CustomerProductRepository customerProducts;private final PricingPlanRepository plans;private final CustomerPricingAssignmentRepository assignments;public CustomerConfigurationService(CustomerRepository c,PaymentProductRepository p,CustomerProductRepository cp,PricingPlanRepository plans,CustomerPricingAssignmentRepository a){customers=c;products=p;customerProducts=cp;this.plans=plans;assignments=a;}
 @Transactional(readOnly=true) public List<CustomerProductResponse> products(UUID customerId){customer(customerId);return customerProducts.findByCustomerIdOrderByProductProductName(customerId).stream().map(this::productResponse).toList();}
 public List<CustomerProductResponse> setProducts(UUID customerId,List<CustomerProductRequest> requests){Customer c=customer(customerId);for(CustomerProductRequest r:requests){if(r.expiryDate()!=null&&r.expiryDate().isBefore(r.activationDate()))throw new IllegalArgumentException("expiryDate cannot precede activationDate");PaymentProduct p=products.findById(r.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found: "+r.productId()));CustomerProduct cp=customerProducts.findByCustomerIdAndProductId(customerId,r.productId()).orElseGet(CustomerProduct::new);cp.setCustomer(c);cp.setProduct(p);cp.setEnabled(r.enabled());cp.setActivationDate(r.activationDate());cp.setExpiryDate(r.expiryDate());customerProducts.save(cp);}return products(customerId);}
 @Transactional(readOnly=true) public List<CustomerPricingResponse> pricing(UUID customerId){customer(customerId);return assignments.findByCustomerIdOrderByEffectiveFromDesc(customerId).stream().map(this::pricingResponse).toList();}
 public CustomerPricingResponse assign(UUID customerId,CustomerPricingRequest r){Customer c=customer(customerId);if(r.effectiveTo()!=null&&r.effectiveTo().isBefore(r.effectiveFrom()))throw new IllegalArgumentException("effectiveTo cannot precede effectiveFrom");PricingPlan p=plans.findById(r.planId()).orElseThrow(()->new ResourceNotFoundException("Pricing plan not found: "+r.planId()));assignments.findByCustomerIdOrderByEffectiveFromDesc(customerId).stream().filter(CustomerPricingAssignment::isActive).forEach(a->{a.setActive(false);assignments.save(a);});CustomerPricingAssignment a=new CustomerPricingAssignment();a.setCustomer(c);a.setPlan(p);a.setEffectiveFrom(r.effectiveFrom());a.setEffectiveTo(r.effectiveTo());a.setActive(true);return pricingResponse(assignments.save(a));}
 private Customer customer(UUID id){return customers.findById(id).orElseThrow(()->new ResourceNotFoundException("Customer not found: "+id));}private CustomerProductResponse productResponse(CustomerProduct x){return new CustomerProductResponse(x.getId(),x.getProduct().getId(),x.getProduct().getProductCode(),x.getProduct().getProductName(),x.isEnabled(),x.getActivationDate(),x.getExpiryDate());}private CustomerPricingResponse pricingResponse(CustomerPricingAssignment x){return new CustomerPricingResponse(x.getId(),x.getPlan().getId(),x.getPlan().getPlanCode(),x.getPlan().getPlanName(),x.getEffectiveFrom(),x.getEffectiveTo(),x.isActive());}}
